import json, base64
for name in ['complete-final', 'pyright-final', 'focused-red', 'postfix-focused']:
    for ext in ['stdout.json', 'stdout']:
        try:
            raw = open(f'{name}.{ext}').read()
        except FileNotFoundError:
            continue
        try:
            obj = json.loads(raw)
            data = base64.b64decode(obj['data']).decode('utf-8', 'replace')
        except (json.JSONDecodeError, KeyError):
            data = raw
        tail = data[-400:] if len(data) > 400 else data
        print(f'===== {name}.{ext} (sha {obj.get(\"sha256\", \"inline\")[:16] if isinstance(obj, dict) else \"raw\"}) =====')
        print(tail)
        print()
